// Скрипт для сервиса удаления фона
document.getElementById('bg-form').addEventListener('submit', async function(e) {
    e.preventDefault();
    
    const fileInput = document.getElementById('image-input');
    const file = fileInput.files[0];
    
    if (!file) {
        showError('Пожалуйста, выберите файл.');
        return;
    }
    
    const formData = new FormData();
    formData.append('image', file);
    
    try {
        const res = await fetch('/remove-bg.php', {
            method: 'POST',
            body: formData
        });
        
        if (!res.ok) {
            const errorData = await res.json();
            showError(errorData.error || 'Ошибка обработки.');
            return;
        }
        
        const blob = await res.blob();
        const url = URL.createObjectURL(blob);
        
        document.getElementById('result-image').src = url;
        document.getElementById('result').style.display = 'block';
        
        document.getElementById('download-btn').onclick = function() {
            const a = document.createElement('a');
            a.href = url;
            a.download = 'no-bg.png';
            a.click();
        };
        
        hideError();
    } catch (error) {
        showError('Ошибка сети.');
    }
});

function showError(message) {
    document.getElementById('error').textContent = message;
    document.getElementById('error').style.display = 'block';
    document.getElementById('result').style.display = 'none';
}

function hideError() {
    document.getElementById('error').style.display = 'none';
}
